{
  "name": "checkout-debug-poc",
  "version": "1.0.0",
  "description": "Deliberately buggy checkout domain for an AI debugging assistant POC.",
  "type": "module",
  "scripts": {
    "test": "vitest run",
    "repro:legacy": "tsx src/reproduceLegacyBug.ts"
  },
  "license": "MIT",
  "devDependencies": {
    "tsx": "^4.19.2",
    "typescript": "^5.6.3",
    "vitest": "^2.1.4"
  }
}

export interface CheckoutResult {
  orderId: string;
  subtotal: number;
  discount: number;
  total: number;
}

export function applyCoupon(order: Order, code: string): Order {
  const coupon = findCoupon(code);
  if (!coupon) {
    logger.warn('Coupon not found', { orderId: order.id, code });
    throw new Error(`Unknown coupon: ${code}`);
  }

  order.coupon = coupon;
  logger.info('Applied coupon to order', { orderId: order.id, code });
  return order;
}

export function checkout(order: Order): CheckoutResult {
  logger.info('Starting checkout', { orderId: order.id, itemCount: order.items.length });

  const subtotal = calculateSubtotal(order);

  let discount = 0;
  if (order.coupon) {
    discount = calculateDiscount(subtotal, order.coupon);
  }

  const total = subtotal - discount;

  logger.info('Checkout complete', { orderId: order.id, subtotal, discount, total });
  return { orderId: order.id, subtotal, discount, total };
}

export function calculateDiscount(subtotal: number, coupon: Coupon): number {
  logger.info('Calculating discount', { code: coupon.code, subtotal });

  // NOTE: this assumes every coupon has a discountType. Coupons created before
  // the migration do not, so this line throws for legacy data.
  const normalizedType = coupon.discountType.toUpperCase();

  let discount: number;
  if (normalizedType === 'PERCENTAGE') {
    discount = subtotal * (coupon.amount / 100);
  } else {
    discount = Math.min(coupon.amount, subtotal);
  }

  logger.info('Discount calculated', { code: coupon.code, type: normalizedType, discount });
  return discount;
}

export function createOrder(): Order {
  const id = `order-${++orderCounter}`;
  logger.info('Created new order', { orderId: id });
  return { id, items: [] };
}

export function addItem(order: Order, product: Product, quantity: number): Order {
  order.items.push({ product, quantity });
  logger.info('Added item to order', { orderId: order.id, sku: product.sku, quantity });
  return order;
}

export function calculateSubtotal(order: Order): number {
  return order.items.reduce(
    (sum: number, item: LineItem) => sum + item.product.unitPrice * item.quantity,
    0,
  );
}

function seed(coupon: Coupon): void {
  coupons.set(coupon.code, coupon);
}

export function findCoupon(code: string): Coupon | undefined {
  return coupons.get(code);
}

export function addCoupon(coupon: Coupon): void {
  coupons.set(coupon.code, coupon);
}

function log(level: Level, message: string, context?: Record<string, unknown>): void {
  const entry = {
    ts: new Date().toISOString(),
    level,
    message,
    ...(context ?? {}),
  };
  const line = JSON.stringify(entry);
  if (level === 'error') console.error(line);
  else console.log(line);
}

export const logger = {
  info: (message: string, context?: Record<string, unknown>) => log('info', message, context),
  warn: (message: string, context?: Record<string, unknown>) => log('warn', message, context),
  error: (message: string, context?: Record<string, unknown>) => log('error', message, context),
};

export interface Product {
  sku: string;
  name: string;
  /** Unit price in whole currency units (e.g. dollars). */
  unitPrice: number;
}

export interface LineItem {
  product: Product;
  quantity: number;
}

export interface Coupon {
  code: string;
  /**
   * Discount type. Every coupon written *after* the migration carries this.
   * Coupons created before the migration ("legacy" coupons) do not.
   */
  discountType: DiscountType;
  /**
   * For PERCENTAGE coupons this is a percentage (10 => 10% off).
   * For FIXED coupons this is an absolute amount off the subtotal.
   */
  amount: number;
}

export interface Order {
  id: string;
  items: LineItem[];
  coupon?: Coupon;
}

import { describe, it, expect } from 'vitest';
import { createOrder, addItem } from '../src/checkout/orderService';
import { checkout, applyCoupon } from '../src/checkout/checkoutService';

describe('checkout without coupons', () => {
  it('totals the subtotal of all line items', () => {
    const order = createOrder();
    addItem(order, { sku: 'A1', name: 'Widget', unitPrice: 20 }, 2);
    addItem(order, { sku: 'B2', name: 'Gadget', unitPrice: 5 }, 1);

    const result = checkout(order);

    expect(result.subtotal).toBe(45);
    expect(result.total).toBe(45);
  });
});

describe('checkout with a coupon', () => {
  it('subtracts the coupon discount from the total', () => {
    const order = createOrder();
    addItem(order, { sku: 'A1', name: 'Widget', unitPrice: 50 }, 2);
    applyCoupon(order, 'SAVE10');

    const result = checkout(order);

    expect(result.subtotal).toBe(100);
    expect(result.discount).toBe(10);
    expect(result.total).toBe(90);
  });
});

import { describe, it, expect } from 'vitest';
import { calculateDiscount } from '../src/checkout/discountService';

describe('calculateDiscount', () => {
  it('applies a percentage discount', () => {
    expect(
      calculateDiscount(100, { code: 'SAVE10', discountType: 'PERCENTAGE', amount: 10 }),
    ).toBe(10);
  });

  it('applies a fixed discount', () => {
    expect(
      calculateDiscount(100, { code: 'FLAT15', discountType: 'FIXED', amount: 15 }),
    ).toBe(15);
  });

  it('never discounts more than the subtotal for fixed coupons', () => {
    expect(
      calculateDiscount(10, { code: 'FLAT15', discountType: 'FIXED', amount: 15 }),
    ).toBe(10);
  });
});
